import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type HandDrawnChartProps = Record<string, any>;

const HandDrawnChart: React.FC<HandDrawnChartProps> = ({
  backgroundColor = "#fdfbf7",
  transparentBackground = false,
  durationInSeconds = 6,
  axisColor = "#2c3e50",
  curveColor = "#e74c3c",
  xAxisLabel = "Dollars Spent",
  yAxisLabel = "Impressions Gained",
  strokeWidth = 6,
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Caveat"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Calculations
  const startX = width * 0.15;
  const startY = height * 0.85;
  const endX = width * 0.85;
  const endY = height * 0.15;

  const chartWidth = endX - startX;
  const chartHeight = startY - endY;

  // Animation Timings
  const yAxisAnimProgress = spring({
    frame: frame - 10,
    fps,
    config: { damping: 12, mass: 0.5 },
  });

  const xAxisAnimProgress = spring({
    frame: frame - 25,
    fps,
    config: { damping: 12, mass: 0.5 },
  });

  const labelsOpacity = interpolate(frame, [40, 60], [0, 1], { extrapolateRight: "clamp" });
  
  const curveProgress = interpolate(frame, [60, 140], [0, 1], { extrapolateRight: "clamp" });

  const arrowOpacity = interpolate(frame, [140, 150], [0, 1], { extrapolateRight: "clamp" });
  
  const gridOpacity = interpolate(frame, [0, 30], [0, 0.15], { extrapolateRight: "clamp" });

  // Generate paths - Scribbled multiple passes for hand-drawn feel
  const yAxisPath = `
    M ${startX + 4} ${startY + 25} Q ${startX - 22} ${startY - chartHeight / 2} ${startX + 1} ${endY - 8}
    M ${startX - 3} ${startY + 15} Q ${startX - 10} ${startY - chartHeight / 2} ${startX + 6} ${endY + 3}
    M ${startX - 0} ${startY + 30} Q ${startX - 15} ${startY - chartHeight / 2} ${startX + 4} ${endY - 2}
  `;
  
  const xAxisPath = `
    M ${startX - 30} ${startY + 4} Q ${startX + chartWidth / 2} ${startY + 22} ${endX + 18} ${startY - 1}
    M ${startX - 15} ${startY - 3} Q ${startX + chartWidth / 2} ${startY + 10} ${endX + 8} ${startY - 6}
    M ${startX - 25} ${startY - 0} Q ${startX + chartWidth / 2} ${startY + 15} ${endX + 12} ${startY - 4}
  `;

  // Loose background grid to enhance the sketch aesthetic
  const gridPath = `
    M ${startX - 15} ${startY - chartHeight * 0.25 + 2} Q ${startX + chartWidth / 2} ${startY - chartHeight * 0.25 - 5} ${endX + 15} ${startY - chartHeight * 0.25 + 1}
    M ${startX - 15} ${startY - chartHeight * 0.5 - 3} Q ${startX + chartWidth / 2} ${startY - chartHeight * 0.5 + 4} ${endX + 15} ${startY - chartHeight * 0.5 - 2}
    M ${startX - 15} ${startY - chartHeight * 0.75 + 1} Q ${startX + chartWidth / 2} ${startY - chartHeight * 0.75 - 3} ${endX + 15} ${startY - chartHeight * 0.75 + 2}
    M ${startX + chartWidth * 0.25 - 2} ${startY + 15} Q ${startX + chartWidth * 0.25 + 4} ${startY - chartHeight / 2} ${startX + chartWidth * 0.25 + 1} ${endY - 15}
    M ${startX + chartWidth * 0.5 + 3} ${startY + 15} Q ${startX + chartWidth * 0.5 - 3} ${startY - chartHeight / 2} ${startX + chartWidth * 0.5 - 1} ${endY - 15}
    M ${startX + chartWidth * 0.75 - 1} ${startY + 15} Q ${startX + chartWidth * 0.75 + 2} ${startY - chartHeight / 2} ${startX + chartWidth * 0.75 + 3} ${endY - 15}
  `;

  // Generate the exponential curve with heavy overlapping passes
  const curveData = useMemo(() => {
    let path = "";
    const steps = 60;
    let finalX = 0;
    let finalY = 0;

    // 3 passes to build up a messy ink/marker look
    for (let pass = 0; pass < 3; pass++) {
      const passOffsetX = (pass - 1) * 4; 
      const passOffsetY = (pass - 1) * 4;

      for (let i = 0; i <= steps; i++) {
        const progress = i / steps; // 0 to 1
        
        // Chaotic intersecting sine waves for scribble effect
        const jitterY = Math.sin(i * 18.12 + pass * 7) * 10 + passOffsetY;
        const jitterX = Math.cos(i * 22.45 + pass * 7) * 10 + passOffsetX;

        const x = startX + (progress * chartWidth) + jitterX;
        // Exponential curve: mapping 0-1 heavily skewed using power of 4
        const yProgress = Math.pow(progress, 4);
        const y = startY - (yProgress * chartHeight) + jitterY;

        if (i === 0) {
          path += `M ${x} ${y}`;
        } else {
          path += ` L ${x} ${y}`;
        }

        // Anchor the arrow purely on the middle line's chaotic end coordinate
        if (pass === 1 && i === steps) {
          finalX = x;
          finalY = y;
        }
      }
    }
    return { path, finalX, finalY };
  }, [startX, startY, chartWidth, chartHeight]);

  // Axis Arrows (multi-stroke to match scribbled axes)
  const yAxisArrow = `
    M ${startX - 18} ${endY + 28} L ${startX + 5} ${endY - 2} L ${startX + 28} ${endY + 22}
    M ${startX - 13} ${endY + 23} L ${startX + 3} ${endY + 2} L ${startX + 23} ${endY + 18}
  `;
  const xAxisArrow = `
    M ${endX - 28} ${startY - 28} L ${endX + 2} ${startY - 5} L ${endX - 18} ${startY + 18}
    M ${endX - 22} ${startY - 22} L ${endX - 2} ${startY - 3} L ${endX - 12} ${startY + 12}
  `;

  // Curve Arrow (messy lines originating exactly at the chaotic ending anchor)
  const curveArrow = `
    M ${curveData.finalX - 35} ${curveData.finalY + 12} L ${curveData.finalX + 2} ${curveData.finalY - 2} L ${curveData.finalX - 8} ${curveData.finalY + 38}
    M ${curveData.finalX - 28} ${curveData.finalY + 18} L ${curveData.finalX - 2} ${curveData.finalY + 2} L ${curveData.finalX - 2} ${curveData.finalY + 32}
  `;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Caveat", overflow: "hidden" }}>
      
      {/* Background SVG for lines and paths */}
      <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0, transition: "none" }}>
        <defs>
          {/* Masks deliberately oversized to catch wide erratic scribbles safely */}
          <clipPath id="y-axis-mask">
            <rect 
              x={startX - 50} 
              y={startY + 50 - ((chartHeight + 150) * yAxisAnimProgress)} 
              width={100} 
              height={(chartHeight + 150) * yAxisAnimProgress} 
            />
          </clipPath>
          <clipPath id="x-axis-mask">
            <rect 
              x={startX - 50} 
              y={startY - 50} 
              width={(chartWidth + 150) * xAxisAnimProgress} 
              height={100} 
            />
          </clipPath>
          <clipPath id="curve-mask">
            <rect 
              x={startX - 40} 
              y={endY - 50} 
              width={(chartWidth + 100) * curveProgress} 
              height={chartHeight + 150} 
            />
          </clipPath>
        </defs>

        {/* Loose Grid Lines */}
        <g 
          fill="none" 
          stroke={axisColor} 
          strokeWidth={Math.max(1, strokeWidth * 0.3)} 
          strokeOpacity={gridOpacity} 
          strokeLinecap="round" 
          strokeLinejoin="round"
        >
          <path d={gridPath} />
        </g>

        {/* X and Y Axes */}
        {/* Adjusted stroke logic so 3 passes don't create a massive blob */}
        <g 
          fill="none" 
          stroke={axisColor} 
          strokeWidth={Math.max(2, strokeWidth * 0.6)} 
          strokeOpacity={0.8}
          strokeLinecap="round" 
          strokeLinejoin="round"
        >
          <path d={yAxisPath} clipPath="url(#y-axis-mask)" />
          <path d={xAxisPath} clipPath="url(#x-axis-mask)" />
          
          {/* Axis Arrows */}
          <path 
            d={yAxisArrow} 
            style={{ 
              opacity: interpolate(yAxisAnimProgress, [0.9, 1], [0, 1], { extrapolateRight: "clamp" }), 
              transition: "none" 
            }} 
          />
          <path 
            d={xAxisArrow} 
            style={{ 
              opacity: interpolate(xAxisAnimProgress, [0.9, 1], [0, 1], { extrapolateRight: "clamp" }), 
              transition: "none" 
            }} 
          />
        </g>

        {/* Exponential Curve */}
        <g 
          fill="none" 
          stroke={curveColor} 
          strokeWidth={Math.max(2, strokeWidth * 0.8)} 
          strokeOpacity={0.8}
          strokeLinecap="round" 
          strokeLinejoin="round"
        >
          <path d={curveData.path} clipPath="url(#curve-mask)" />
          {/* Curve Arrow showing momentum */}
          <path 
            d={curveArrow} 
            style={{ 
              opacity: arrowOpacity, 
              transition: "none" 
            }} 
          />
        </g>
      </svg>

      {/* Text Labels with slight skewed rotation for sketch feel */}
      <div
        style={{
          position: "absolute",
          top: startY - chartHeight / 2,
          left: startX - 120,
          transform: "translate(-50%, -50%) rotate(-93deg)",
          color: axisColor,
          fontSize: "52px",
          fontWeight: 600,
          opacity: labelsOpacity,
          whiteSpace: "nowrap",
          letterSpacing: "0.05em",
          transition: "none"
        }}
      >
        {yAxisLabel}
      </div>

      <div
        style={{
          position: "absolute",
          top: startY + 60,
          left: startX + chartWidth / 2,
          transform: "translate(-50%, 0) rotate(-2deg)",
          color: axisColor,
          fontSize: "52px",
          fontWeight: 600,
          opacity: labelsOpacity,
          whiteSpace: "nowrap",
          letterSpacing: "0.05em",
          transition: "none"
        }}
      >
        {xAxisLabel}
      </div>
      
    </AbsoluteFill>
  );
};

export default HandDrawnChart;